// The three "or start from one of these examples" starters on Discovery.
//
// These used to be three hardcoded strings (an Operations Manager, someone in
// Sales, a Senior Director of Enablement). Even a learner whose title matched one
// of them exactly said none of them fit — because a generic role sentence isn't
// recognisable as YOUR work. The specific tasks and goals someone typed during
// onboarding are.
//
// Built deterministically from the saved profile rather than generated by a model:
// it's instant (the whole point of these is a fast start, so no spinner and no
// swapping text under the reader), it can't invent a role they don't have, and it
// reuses answers they already gave. Falls back to the generic set when there's no
// profile yet.

// Kept as the fallback for a learner with no usable profile — someone who hasn't
// finished onboarding, or a demo account.
export const GENERIC_EXAMPLES = [
  "I'm an Operations Manager. My typical day: 3-4 meetings, reviewing project status updates, planning next quarter, and writing reports.",
  "I'm in Sales. I spend mornings on prospect research, then write outreach emails, take customer calls, and update CRM in the afternoon.",
  'Senior Director of Enablement. I lead a team that builds training. I review their content, run program launches, write executive updates, and meet with stakeholders.',
];

// Exported for lib/game-topics.js, which builds the same kind of
// profile-derived starters for the "Surprise me" button on Games.
export function cleanList(value) {
  if (!Array.isArray(value)) return [];
  return value
    .map((v) => (typeof v === 'string' ? v.trim() : ''))
    .filter(Boolean);
}

// "a" vs "an" — only ever used in front of a job title.
function article(word) {
  return /^[aeiou]/i.test(word || '') ? 'an' : 'a';
}

// Onboarding tasks/goals are stored however the learner picked them, so they may
// arrive capitalized ("Reviewing content"). Lowercase the first letter when the
// phrase is being dropped mid-sentence — but leave acronyms and proper nouns
// alone, since "HCP" must not become "hCP".
export function midSentence(phrase) {
  const s = (phrase || '').trim();
  if (!s) return '';
  const firstWord = s.split(/\s+/)[0];
  if (firstWord.length > 1 && firstWord === firstWord.toUpperCase()) return s;
  return s.charAt(0).toLowerCase() + s.slice(1);
}

// "a, b and c" — an Oxford-comma-free join, which reads better inside a sentence.
function joinPhrases(items) {
  const list = items.map(midSentence).filter(Boolean);
  if (list.length <= 1) return list[0] || '';
  if (list.length === 2) return `${list[0]} and ${list[1]}`;
  return `${list.slice(0, -1).join(', ')} and ${list[list.length - 1]}`;
}

function endWithPeriod(text) {
  const s = (text || '').trim();
  if (!s) return '';
  return /[.!?]$/.test(s) ? s : `${s}.`;
}

// How the learner describes their own position. Prefers the Snowflake title, then
// the sub-team, then the department.
function roleSentence(profile) {
  const title = (profile?.title || '').trim();
  if (title) return `I'm ${article(title)} ${title}.`;
  const team = (profile?.sub_team || '').trim() || (profile?.department || '').trim();
  return team ? `I work in ${team}.` : '';
}

// Three starters, each a DIFFERENT shape so they read as options rather than one
// sentence rephrased: the whole day, one task in depth, and a goal.
export function buildDiscoveryExamples(profile) {
  const tasks = cleanList(profile?.top_tasks);
  const goals = cleanList(profile?.goals);
  const role = roleSentence(profile);

  // Without tasks there's nothing specific enough to beat the generic set — a
  // bare "I work in Enablement." is a worse starter than a vivid generic one.
  if (!tasks.length) return GENERIC_EXAMPLES;

  const examples = [];

  // 1. The whole day — mirrors the input's own prompt ("describe your typical day").
  const dayList = joinPhrases(tasks.slice(0, 4));
  examples.push(endWithPeriod(`${role} My typical day: ${dayList}`.trim()));

  // 2. One task, in depth — invites a narrower, more useful answer than the day view.
  const biggest = midSentence(tasks[0]);
  examples.push(
    endWithPeriod(
      `A big chunk of my week goes to ${biggest} — I'd like to spend less time on the repetitive parts of that`,
    ),
  );

  // 3. A goal, anchored to a real task so it isn't abstract. Falls back to a
  //    second task when they set no goals.
  //
  //    Phrased "My goal right now: X" rather than "I want to X" on purpose. The
  //    built-in goals are verb phrases ("Integrate AI into my daily workflow"),
  //    but onboarding also lets people type their own, which are often noun
  //    phrases — and "I want to better dashboards I can trust" is broken English.
  //    The colon form reads correctly either way.
  const secondTask = tasks[1] ? midSentence(tasks[1]) : biggest;
  if (goals.length) {
    examples.push(
      endWithPeriod(`My goal right now: ${midSentence(goals[0])}. Most of my time goes to ${secondTask}`),
    );
  } else {
    examples.push(
      endWithPeriod(`${secondTask} is something I do often and I'm sure there's a faster way`.trim().replace(/^./, (c) => c.toUpperCase())),
    );
  }

  // De-dupe in case someone entered a single task and the shapes collapsed.
  return [...new Set(examples.filter(Boolean))];
}
